              onChange={(e) => updateSettings({ customSoundVolume: parseFloat(e.target.value) })}
              className="w-32 accent-primary"
            />
            <span className="text-xs text-muted-foreground w-8">
              {Math.round(settings.customSoundVolume * 100)}%
            </span>
