      const unreadWorktreePaths = Object.fromEntries(
        Object.entries(state.unreadWorktreePaths).filter(([path]) => validWorktreePaths.has(path)),
      );
      return {
        ...state,
        worktrees: action.worktrees,
        activeWorktreePath,
